export type HersheyFaceId = keyof typeof HERSHEY_FACES;

/** Curated picker order — visually distinct faces only. The full HERSHEY_FACES
 *  set keeps every id valid, but several entries render as near-identical
 *  repeats (the Times trio duplicates the Serif family, "Blackletter"
 *  duplicates Old English, "Formal Script" duplicates Script light) and the
 *  Greek/Cyrillic faces draw the wrong alphabet for typed Latin text. Font
 *  pickers should list these, in this order. */
export const HERSHEY_PICKER_IDS: HersheyFaceId[] = [
  "sans", "sansMed", "futuram", "readability", "readabilityItalic",
  "nixish", "nixishItalic", "tech", "osmotron",
  "serif", "serifItalic", "serifBold", "serifBoldItalic",
  "script", "scriptBold", "cursive", "allure", "elfin", "felix",
  "gothic", "gothicger", "gothicita",
];
